package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;
import org.json.*;import java.util.*;
import org.opencv.android.*;import org.opencv.core.*;import org.opencv.imgproc.Imgproc;

/** Document normalization followed by actual bundled Korean/Latin OCR and source-linked fields. */
final class DocumentWorkflow {
 static void run(Context c,String id,Bitmap input,OneModelRunner.Cancel cancel,OneModelRunner.Result r)throws Exception{
  if(!Arrays.asList("doc-ocr-ko","doc-ocr-latin").contains(id)&&!ModelPlusPolicy.paddle(id))throw new IllegalArgumentException("document model");
  long load=SystemClock.elapsedRealtime();OneTextEngine engine=new OneTextEngine(c,id,cancel);r.modelSha256=engine.modelSha256;r.engineCreated=true;r.loadMs=SystemClock.elapsedRealtime()-load;
  Prepared prepared=null;
  try{long infer=SystemClock.elapsedRealtime();prepared=prepare(input,cancel);ExpansionImageRunner.check(cancel);PhotoVisionEngine.Ocr found=engine.ocr(prepared.bitmap);ExpansionImageRunner.check(cancel);DocumentFields.Fields fields=DocumentFields.parse(found.text);
   r.image=prepared.bitmap.copy(Bitmap.Config.ARGB_8888,true);Canvas canvas=new Canvas(r.image);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(0xff0068f8);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(2,r.image.getWidth()/400f));for(PhotoVisionEngine.TextBox box:found.boxes)canvas.drawRect(box.left*r.image.getWidth(),box.top*r.image.getHeight(),box.right*r.image.getWidth(),box.bottom*r.image.getHeight(),p);
   r.metrics.put("characters",found.text.length()).put("blocks",found.boxes.size()).put("merchant",fields.merchant).put("date",fields.date).put("total",fields.total).put("currency",fields.currency).put("totalSourceLine",fields.totalSource).put("nonemptyLines",fields.nonemptyLines).put("perspectiveCorrected",prepared.corrected).put("pipeline","OpenCV quadrilateral perspective + CLAHE grayscale → selected OCR model → source-linked field rules").put("ocrModel",engine.modelId).put("ocrBackend",ModelPlusPolicy.paddle(id)?"PaddleOCR ONNX":"ML Kit 16.0.1").put("outputWidth",r.image.getWidth()).put("outputHeight",r.image.getHeight()).put("outputCoordinateSpace","rectified enhanced document; OCR boxes normalized to this displayed output").put("fieldExtraction","deterministic labeled-line rules; not an LLM");
   r.metrics.put("recognizedText",found.text);r.summary=fields.total.isEmpty()?"문서 "+found.text.length()+"자 · "+found.boxes.size()+"영역":"합계 "+fields.total+(fields.currency.isEmpty()?"":" "+fields.currency);
   r.detail="상호  "+display(fields.merchant)+"\n날짜  "+display(fields.date)+"\n합계  "+display(fields.total)+(fields.currency.isEmpty()?"":" "+fields.currency)+"\n\n인식한 원문\n"+found.text;r.inferenceMs=SystemClock.elapsedRealtime()-infer;
  }finally{try{engine.close();r.engineCloseReturned=true;}finally{if(prepared!=null)prepared.bitmap.recycle();}}
 }
 private static String display(String s){return s.isEmpty()?"미검출":s;}
 static final class Prepared{final Bitmap bitmap;final boolean corrected;Prepared(Bitmap b,boolean c){bitmap=b;corrected=c;}}
 private static Prepared prepare(Bitmap input,OneModelRunner.Cancel cancel)throws Exception{
  if(!OpenCVLoader.initLocal())throw new java.io.IOException("document image engine");Mat rgba=new Mat(),rgb=new Mat(),gray=new Mat(),blur=new Mat(),edges=new Mat(),hierarchy=new Mat(),warped=new Mat(),contrast=new Mat();List<MatOfPoint> contours=new ArrayList<>();boolean corrected=false;Bitmap result=null;
  try{Utils.bitmapToMat(input,rgba);Imgproc.cvtColor(rgba,rgb,Imgproc.COLOR_RGBA2RGB);Imgproc.cvtColor(rgb,gray,Imgproc.COLOR_RGB2GRAY);Imgproc.GaussianBlur(gray,blur,new Size(5,5),0);Imgproc.Canny(blur,edges,60,180);Imgproc.findContours(edges,contours,hierarchy,Imgproc.RETR_EXTERNAL,Imgproc.CHAIN_APPROX_SIMPLE);contours.sort((a,b)->Double.compare(Math.abs(Imgproc.contourArea(b)),Math.abs(Imgproc.contourArea(a))));ExpansionImageRunner.check(cancel);
   for(int n=0;n<Math.min(8,contours.size());n++){MatOfPoint2f curve=new MatOfPoint2f(contours.get(n).toArray()),poly=new MatOfPoint2f();try{double area=Math.abs(Imgproc.contourArea(contours.get(n)));if(area<gray.total()*.20)continue;Imgproc.approxPolyDP(curve,poly,Imgproc.arcLength(curve,true)*.025,true);org.opencv.core.Point[] q=poly.toArray();if(q.length!=4)continue;MatOfPoint test=new MatOfPoint(q);boolean convex;try{convex=Imgproc.isContourConvex(test);}finally{test.release();}if(!convex)continue;org.opencv.core.Point[] ordered=order(q);if(ordered==null)continue;double w=Math.max(distance(ordered[0],ordered[1]),distance(ordered[2],ordered[3])),h=Math.max(distance(ordered[0],ordered[3]),distance(ordered[1],ordered[2]));if(w<160||h<160)continue;double scale=Math.min(1,1600/Math.max(w,h));int ow=(int)Math.round(w*scale),oh=(int)Math.round(h*scale);MatOfPoint2f src=new MatOfPoint2f(ordered),dst=new MatOfPoint2f(new org.opencv.core.Point(0,0),new org.opencv.core.Point(ow-1,0),new org.opencv.core.Point(ow-1,oh-1),new org.opencv.core.Point(0,oh-1));Mat transform=Imgproc.getPerspectiveTransform(src,dst);try{Imgproc.warpPerspective(gray,warped,transform,new Size(ow,oh));corrected=true;}finally{transform.release();src.release();dst.release();}break;}finally{curve.release();poly.release();}}
   Mat working=corrected?warped:gray;org.opencv.imgproc.CLAHE clahe=Imgproc.createCLAHE(2,new Size(8,8));try{clahe.apply(working,contrast);}finally{clahe.collectGarbage();}result=Bitmap.createBitmap(contrast.cols(),contrast.rows(),Bitmap.Config.ARGB_8888);Utils.matToBitmap(contrast,result);ExpansionImageRunner.check(cancel);Bitmap returned=result;result=null;return new Prepared(returned,corrected);
  }finally{if(result!=null)result.recycle();for(MatOfPoint m:contours)m.release();rgba.release();rgb.release();gray.release();blur.release();edges.release();hierarchy.release();warped.release();contrast.release();}
 }
 private static double distance(org.opencv.core.Point a,org.opencv.core.Point b){return Math.hypot(a.x-b.x,a.y-b.y);}
 private static org.opencv.core.Point[] order(org.opencv.core.Point[] q){org.opencv.core.Point tl=q[0],tr=q[0],br=q[0],bl=q[0];for(org.opencv.core.Point p:q){if(p.x+p.y<tl.x+tl.y)tl=p;if(p.x+p.y>br.x+br.y)br=p;if(p.x-p.y>tr.x-tr.y)tr=p;if(p.x-p.y<bl.x-bl.y)bl=p;}Set<org.opencv.core.Point> unique=new HashSet<>(Arrays.asList(tl,tr,br,bl));return unique.size()==4?new org.opencv.core.Point[]{tl,tr,br,bl}:null;}
}
